(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const mx = x+w1x, my = y+w1y;
  const w2x = Math.sin(my*0.025-t*0.15)*8 + Math.cos(mx*0.02+t*0.1)*6;
  const w2y = Math.cos(mx*0.022+t*0.18)*8 + Math.sin(my*0.019-t*0.12)*6;
  const sx = mx+w2x, sy = my+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.5],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.0],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 1.5],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 2.0],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 2.5],
    [80+Math.sin(t*0.45+3)*110, 40+Math.cos(t*0.65)*60, 0.055, 2.1, 3.0],
    [400+Math.cos(t*0.55+1)*70, 200+Math.sin(t*0.75+2)*50, 0.11, 1.8, 3.5],
    [200+Math.sin(t*0.38+4.5)*90, 220+Math.cos(t*0.48+0.5)*70, 0.075, 2.4, 4.0],
    [300+Math.cos(t*0.42+2.5)*80, 30+Math.sin(t*0.58+1.5)*55, 0.065, 2.0, 4.5]
  ];
  let aS=0, iS=0, mS=0;
  for(const [sX,sY,f,sp,ph] of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const w=Math.sin(d*f-t*sp+ph)*Math.exp(-d*0.003);
    aS+=Math.sin(d*f-t*sp+ph);
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5+ph);
    mS+=Math.cos(d*f*0.5-t*sp*0.8+ph*0.5)*Math.sin(d*f*1.3+t*sp*0.3);
  }
  const act=aS/10, inh=iS/10, mod=mS/10;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    +Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2
    +Math.sin(sx*0.07*sy*0.001+t*0.6)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4
    +Math.sin(dist*0.08-ang*2+t*0.9)*0.15+Math.cos(dist*0.03+ang*6-t*2.1)*0.1;
  const moire=Math.sin(sx*0.12)*Math.sin(sy*0.12)*Math.cos((sx-sy)*0.08+t*1.5)*0.3;
  const pulse=1+Math.sin(t*0.8)*0.08+Math.sin(t*1.3+1)*0.05;
  const feed=Math.tanh((act-inh*0.65+bg*0.3+spiral+moire*0.4+mod*0.25)*2.0*pulse);
  const diff=Math.tanh((feed+Math.sin(sx*0.08+sy*0.06-t*0.7)*0.3)*1.8);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const ridge=Math.abs(feed)>0.6?Math.sin(feed*8)*0.15:0;
  const blend=diff*0.6+cell*0.2+ridge*0.2, v=blend*0.5+0.5;
  const pal=[
    [6,12,52],[12,45,88],[18,85,115],[25,130,130],[60,160,120],
    [140,175,80],[195,175,55],[215,140,60],[205,95,65],[165,55,60],
    [110,30,55],[55,18,48],[20,12,42],[6,12,52]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const sf=f*f*(3-2*f);
  const lum=0.82+Math.sin(diff*Math.PI)*0.18+Math.abs(feed)>0.75?0.08:0;
  const edge=Math.abs(feed)>0.65?1.18:Math.abs(feed)>0.4?1.05:0.95;
  const glow=Math.max(0,1-dist/220)*0.12*Math.max(0,feed);
  return [
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*sf)*lum*edge+glow*40)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*sf)*lum*edge+glow*55)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*sf)*lum*edge+glow*80)|0)
  ];
}
